<div class="fields two"><label>Jenis<select name="type"><option value="piutang" @selected(($debt?->type??old('type'))==='piutang')>Piutang pelanggan</option><option value="utang" @selected(($debt?->type??old('type'))==='utang')>Utang supplier</option></select></label><label>Nama pelanggan / supplier<input name="party" value="{{ $debt?->party??old('party') }}" maxlength="150" required></label><label>Nomor WhatsApp<input name="phone" type="tel" maxlength="25" value="{{ $debt?->phone??old('phone') }}"></label><label>Total kasbon (Rp)<input name="total" type="number" min="{{ max(1,$debt?->paid??0) }}" max="1000000000000" step="1" value="{{ $debt?->total??old('total') }}" required></label><label>Jatuh tempo<input type="date" name="due_date" value="{{ $debt?->due_date->toDateString()??old('due_date',today()->addWeek()->toDateString()) }}" required></label><label>Catatan<input name="note" maxlength="1000" value="{{ $debt?->note??old('note') }}"></label></div>
